import {drawFormation} from './drafter-share-render.mjs';
import {accountUser} from './formation-api.mjs';
export function installShare({getDraft,getKnown,getSummaries,copyLink,publish}){
 const make=(tag,text,cls)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e};
 const dialog=make('dialog',undefined,'share-dialog');dialog.setAttribute('aria-labelledby','share-heading');const head=make('div',undefined,'modal-head'),title=make('h3','Share this formation');title.id='share-heading';const close=make('button','×','btn secondary share-close-icon');close.type='button';close.setAttribute('aria-label','Close share');close.onclick=()=>dialog.close();head.append(title,close);
 const body=make('div',undefined,'share-layout'),previewColumn=make('div',undefined,'share-preview-column'),toolbar=make('div',undefined,'share-preview-toolbar'),themes=make('div',undefined,'segmented'),preview=make('div',undefined,'share-preview'),canvas=make('canvas'),controls=make('div',undefined,'share-controls');preview.dataset.format='grid';preview.append(canvas);toolbar.append(themes);previewColumn.append(toolbar,preview);let theme='light';
 const field=(text,id,tag='input')=>{const label=make('label',undefined,'field'),input=make(tag);input.id=id;input.maxLength=tag==='textarea'?500:80;label.append(make('span',text),input);controls.append(label);return input};
 const formationName=field('Formation name','share-title'),author=field('Your name (optional)','share-author'),notes=field('Notes (optional)','share-notes','textarea');author.placeholder='Leave empty to skip';notes.rows=4;notes.placeholder='Add formation notes';
 const actions=make('div',undefined,'share-actions'),feedback=make('p','','caption');feedback.setAttribute('role','status');controls.append(actions,feedback);body.append(previewColumn,controls);dialog.append(head,body);document.body.append(dialog);
 let generation=0;
 async function render(){const token=++generation;feedback.textContent='Preparing preview…';try{const buffer=document.createElement('canvas');await drawFormation({canvas:buffer,draft:getDraft(),known:getKnown(),summaries:getSummaries(),title:formationName.value,author:author.value,notes:notes.value,theme,everything:false});if(token!==generation)return;canvas.width=buffer.width;canvas.height=buffer.height;canvas.getContext('2d').drawImage(buffer,0,0);canvas.style.width='';preview.dataset.theme=theme;feedback.textContent='Preview ready.'}catch(error){if(token===generation)feedback.textContent=error.message||'Could not render image.'}}
 for(const value of ['light','dark']){const b=make('button',value==='light'?'Light':'Dark');b.dataset.previewTheme=value;b.onclick=()=>{theme=value;themes.querySelectorAll('button').forEach(e=>e.setAttribute('aria-pressed',String(e===b)));render()};themes.append(b)}
 const remember=()=>{getDraft().shareAuthor=author.value;getDraft().shareNotes=notes.value;const editor=document.getElementById('formation-notes');if(editor&&editor.value!==notes.value){editor.value=notes.value;editor.dispatchEvent(new Event('input'))}getDraft().shareTheme=theme};for(const input of [formationName,author,notes])input.oninput=()=>{remember();render()};
 const blob=()=>new Promise(resolve=>canvas.toBlob(resolve,'image/png'));const filename=()=>((formationName.value||'formation').replace(/[^a-z0-9_-]/gi,'-').slice(0,60)||'formation')+'.png';
 const action=(label,cls,callback)=>{const button=make('button',label,'btn '+cls);button.onclick=async()=>{button.disabled=true;try{remember();await callback()}catch(e){feedback.textContent=e.message||'Action unavailable.'}finally{button.disabled=false}};actions.append(button)};
 action('Download PNG','secondary',async()=>{const url=URL.createObjectURL(await blob()),a=make('a');a.href=url;a.download=filename();a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);feedback.textContent='PNG downloaded.'});
 action('Copy image','secondary',async()=>{if(!globalThis.ClipboardItem||!navigator.clipboard?.write)throw Error('Copy image is unavailable. Use Download PNG.');await navigator.clipboard.write([new ClipboardItem({'image/png':await blob()})]);feedback.textContent='Image copied.'});
 action('Publish','',async()=>{getDraft().name=formationName.value;document.getElementById('draft-name').value=formationName.value;dialog.close();await publish?.()});
 return {open:async()=>{theme=getDraft().shareTheme==='dark'?'dark':'light';formationName.value=getDraft().name;author.value=getDraft().shareAuthor||'';notes.value=getDraft().shareNotes||'';dialog.showModal();themes.querySelectorAll('button').forEach(e=>e.setAttribute('aria-pressed',String(e.dataset.previewTheme===theme)));render();if(!author.value){try{const user=await accountUser(),meta=user?.user_metadata;if(meta&&!author.value){author.value=meta.display_name||meta.full_name||meta.global_name||meta.name||meta.user_name||meta.preferred_username||'';remember();render()}}catch{}}}};
}
